import{az as i,P as t,Q as a,aQ as e}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"面试题/http.md","filePath":"面试题/http.md","lastUpdated":1782478366000}'),o={name:"面试题/http.md"};function s(r,l,n,h,p,d){return t(),a("div",null,[...l[0]||(l[0]=[e('<h2 id="http完整运行流程" tabindex="-1">http完整运行流程 <a class="header-anchor" href="#http完整运行流程" aria-label="Permalink to “http完整运行流程”">​</a></h2><ul><li>应用层：解析 域名、ip、请求信息</li><li>传输层： 使用 TCP协议进行连接</li><li>网络层： 梳理打包传输的数据</li><li>链路层：处理连接网络硬件的部分</li></ul><h2 id="http" tabindex="-1">http <a class="header-anchor" href="#http" aria-label="Permalink to “http”">​</a></h2><ul><li>http 是无状态的，可以使用 keep-alive 持久连接，一方中断则会断开</li><li>http 使用明文传输，可被监听。（使用charles等抓包工具可直接查看内容）</li><li>http 不会验证对方，可被伪装。（自己的网站被运营商插入过广告）</li><li>http 无法确定数据的完整性，可被篡改</li></ul><h2 id="https" tabindex="-1">https <a class="header-anchor" href="#https" aria-label="Permalink to “https”">​</a></h2><p>协议上使用 SSL 或 TSL 安全协议层，负责网络连接的加密。 访问https网站时客户端会与服务器先建立一个安全的连接通道，然后服务器发送一份证书到客户端进行验证，将客户端的数据包使用对称密钥进行加密，然后发送到服务器。</p><h2 id="dns-domain-name-system-是做什么的" tabindex="-1">DNS(Domain Name System) 是做什么的 <a class="header-anchor" href="#dns-domain-name-system-是做什么的" aria-label="Permalink to “DNS(Domain Name System) 是做什么的”">​</a></h2><p>将域名解析成IP</p><h2 id="输入-url-到-页面发生了哪些" tabindex="-1">输入 url 到 页面发生了哪些 <a class="header-anchor" href="#输入-url-到-页面发生了哪些" aria-label="Permalink to “输入 url 到 页面发生了哪些”">​</a></h2><ul><li>DNS 解析域名IP、解析请求信息</li><li>通过 TCP协议 向服务器建立连接，进行三次握手</li><li>服务器返回数据和状态码</li><li>浏览器进行渲染</li></ul><h2 id="建立-tcp-协议会增加请求延时" tabindex="-1">建立 TCP 协议会增加请求延时 <a class="header-anchor" href="#建立-tcp-协议会增加请求延时" aria-label="Permalink to “建立 TCP 协议会增加请求延时”">​</a></h2><ul><li>资源打包、合并请求</li><li>使用缓存，减少请求</li><li>使用 keep-alive</li><li>使用多个域名请求，增加并发量；使用 http2 的多线路复用技术</li></ul><h2 id="get-和-post-有什么区别" tabindex="-1">get 和 post 有什么区别 <a class="header-anchor" href="#get-和-post-有什么区别" aria-label="Permalink to “get 和 post 有什么区别”">​</a></h2><ul><li>两者都是用于发送数据请求，但更多的是 get 用于查询、post 用于写入，相较于安全无差，都可以使用抓包工具进行查看</li><li>get <ul><li>将发送的数据请求放在 url 中 直接暴露了传递信息</li><li>根据浏览器、服务器有长度限制</li><li>可以实现 jsonp 跨域</li></ul></li><li>post <ul><li>可以将数据放在 url 和 body 中</li><li>没有长度限制</li><li>需要进行跨域</li></ul></li></ul><h2 id="post-为什么会发送两次" tabindex="-1">post 为什么会发送两次 <a class="header-anchor" href="#post-为什么会发送两次" aria-label="Permalink to “post 为什么会发送两次”">​</a></h2><ol><li>并不是两次 post 请求， 首次是 options <strong>跨域</strong>预检请求</li></ol><h2 id="为什么需要-options-预检请求" tabindex="-1">为什么需要 options 预检请求 <a class="header-anchor" href="#为什么需要-options-预检请求" aria-label="Permalink to “为什么需要 options 预检请求”">​</a></h2><ul><li>为了确保跨域请求的安全性，浏览器会先发送 options 预检请求，服务器会根据预检请求判断是否允许跨域请求。</li><li>如果服务器允许跨域请求，浏览器会发送实际的 post 请求。</li><li>如果服务器拒绝跨域请求，浏览器会直接拒绝 post 请求， 报跨域错误。</li></ul><h2 id="什么请求会触发-options-预检" tabindex="-1">什么请求会触发 options 预检 <a class="header-anchor" href="#什么请求会触发-options-预检" aria-label="Permalink to “什么请求会触发 options 预检”">​</a></h2><ol><li>请求不是 GET/POST/HEAD</li><li>请求头中包含自定义的请求头，如 Content-Type: application/json、 X-Custom-Header: 123、Authorization、token、X-Requested-With 等</li></ol><h2 id="怎么避免-options-预检请求" tabindex="-1">怎么避免 options 预检请求 <a class="header-anchor" href="#怎么避免-options-预检请求" aria-label="Permalink to “怎么避免 options 预检请求”">​</a></h2><ol><li>后端配置跨域请求</li></ol><ul><li>增加 Access-Control-Allow-Origin: * 头</li><li>增加 Access-Control-Allow-Methods: GET, POST, HEAD, OPTIONS, PUT, DELETE 头</li><li>增加 Access-Control-Allow-Headers: Content-Type, X-Custom-Header: 123 头</li><li>增加 Access-Control-Max-Age: 86400 头 // 表示该预检结果可缓存 24 小时。有效期内，同类型跨域请求不会重复发送 OPTIONS。</li><li>增加 Access-Control-Allow-Credentials: true 头</li><li>增加 Access-Control-Expose-Headers: X-Custom-Header: 123 头</li></ul><ol start="2"><li>前端配置跨域请求</li></ol><ul><li>增加 withCredentials: true 头</li><li>增加 mode: &#39;cors&#39; 头</li></ul><ol start="3"><li>同域部署，不需要跨域请求</li><li>请求头仅包含浏览器安全范围内的头 Accept、Accept-Language、Content-Language 等</li><li>POST 的 Content-Type 仅限以下三种：</li></ol><ul><li>application/x-www-form-urlencoded（表单默认提交格式）</li><li>multipart/form-data（文件上传格式）</li><li>text/plain（普通文本格式）</li></ul><h2 id="post-发送options预检请求会有什么影响" tabindex="-1">post 发送options预检请求会有什么影响 <a class="header-anchor" href="#post-发送options预检请求会有什么影响" aria-label="Permalink to “post 发送options预检请求会有什么影响”">​</a></h2><ul><li>增加了请求次数，增加了网络开销</li><li>增加了请求时间，增加了响应时间</li><li>增加了请求头，增加了请求头大小</li><li>预检请求会增加一次网络往返，对接口性能有轻微影响</li></ul><h2 id="cookie-与-session-的跨域名共享规则" tabindex="-1">Cookie 与 Session 的跨域名共享规则 <a class="header-anchor" href="#cookie-与-session-的跨域名共享规则" aria-label="Permalink to “Cookie 与 Session 的跨域名共享规则”">​</a></h2><p>直接给出明确结论，分两种核心场景：</p><ol><li>同根域名场景（shturl. 和 a.shturl.、b.shturl.）：默认不能直接共享，但通过配置 Cookie 的 Domain 属性，可以实现全子域名共享 Cookie，进而共享 Session。</li><li>完全不同根域名场景（shturl. 和 yyy.com）：浏览器同源策略严格禁止，任何前端 / 后端手段都无法直接互相读取或共享 Cookie，Session 自然也无法直接共享。</li></ol>',32)])])}const P=i(o,[["render",s]]);export{m as __pageData,P as default};
